namespace docking;



using docking.action;
using docking.action;
using docking.actions;
using docking.tool;
using generic.theme;
using ghidra.util;

class ShowWindowAction : DockingAction, AutoGeneratedDockingAction, Comparable<ShowWindowAction> {

	private static readonly Icon ICON = new GIcon("icon.window");
	private static readonly string MENU_WINDOW = "&" + DockingWindowManager.COMPONENT_MENU_NAME;

	private static readonly int MAX_LENGTH = 40;

	private DetachedWindowNode node;

	private static string truncateTitleAsNeeded(string title) {
		if (title.length() <= MAX_LENGTH) {
			return title;
		}

		return title.substring(0, MAX_LENGTH - 3) + "...";
	}

	ShowWindowAction(DetachedWindowNode node) : base(truncateTitleAsNeeded(node.getTitle()), DockingWindowManager.DOCKING_WINDOWS_OWNER,
			false)
    {
		this.node = node;

		setMenuBarData(new MenuData(new string[] { MENU_WINDOW, getName() }, ICON, "WindowGroup"));
		setHelpLocation(new HelpLocation(ToolConstants.TOOL_HELP_TOPIC, "DefaultTools")); // somewhat arbitrary location
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		DockingWindowManager manager = DockingWindowManager.getActiveInstance();
		manager.toFront(node.getWindow());
	}

	/* @Override */
	public int compareTo(ShowWindowAction o) {
		return getName().compareToIgnoreCase(o.getName());
	}
}
